{"file_path": "src/hooks/core/use-keyboard-shortcuts.ts", "initial_content": "/**
 * Keyboard Shortcuts Hook
 * Provides keyboard navigation and shortcuts for flow builder
 */

'use client';

import { useEffect, useCallback } from 'react';

export interface KeyboardShortcut {
  key: string;
  ctrl?: boolean;
  shift?: boolean;
  alt?: boolean;
  meta?: boolean;
  action: () => void;
  description: string;
  category?: string;
}

interface UseKeyboardShortcutsOptions {
  enabled?: boolean;
  preventDefault?: boolean;
}

export function useKeyboardShortcuts(
  shortcuts: KeyboardShortcut[],
  options: UseKeyboardShortcutsOptions = {}
) {
  const { enabled = true, preventDefault = true } = options;

  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!enabled) return;

      // Find matching shortcut
      const shortcut = shortcuts.find((s) => {
        const keyMatch = s.key.toLowerCase() === event.key.toLowerCase();
        const ctrlMatch = s.ctrl ? event.ctrlKey || event.metaKey : !event.ctrlKey && !event.metaKey;
        const shiftMatch = s.shift ? event.shiftKey : !event.shiftKey;
        const altMatch = s.alt ? event.altKey : !event.altKey;

        return keyMatch && ctrlMatch && shiftMatch && altMatch;
      });

      if (shortcut) {
        if (preventDefault) {
          event.preventDefault();
        }
        shortcut.action();
      }
    },
    [shortcuts, enabled, preventDefault]
  );

  useEffect(() => {
    if (!enabled) return;

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown, enabled]);

  return {
    shortcuts,
    enabled,
  };
}

// Predefined shortcut helpers
export const COMMON_SHORTCUTS = {
  SAVE: { key: 's', ctrl: true, description: 'Save flow' },
  UNDO: { key: 'z', ctrl: true, description: 'Undo' },
  REDO: { key: 'z', ctrl: true, shift: true, description: 'Redo' },
  DELETE: { key: 'Delete', description: 'Delete selected step' },
  BACKSPACE: { key: 'Backspace', description: 'Delete selected step' },
  ESCAPE: { key: 'Escape', description: 'Deselect/Close' },
  COPY: { key: 'c', ctrl: true, description: 'Copy step' },
  PASTE: { key: 'v', ctrl: true, description: 'Paste step' },
  DUPLICATE: { key: 'd', ctrl: true, description: 'Duplicate step' },
  NEW: { key: 'n', ctrl: true, description: 'New flow' },
  SEARCH: { key: 'k', ctrl: true, description: 'Search steps' },
  HELP: { key: '?', shift: true, description: 'Show help' },
};
"}

{"file_path": "src/hooks/core/use-undo-redo.ts", "initial_content": "/**
 * Undo/Redo Hook
 * Provides undo/redo functionality for state management
 */

'use client';

import { useState, useCallback, useRef } from 'react';

interface UseUndoRedoOptions<T> {
  maxHistory?: number;
  onUndo?: (state: T) => void;
  onRedo?: (state: T) => void;
}

export function useUndoRedo<T>(
  initialState: T,
  options: UseUndoRedoOptions<T> = {}
) {
  const { maxHistory = 50, onUndo, onRedo } = options;

  const [state, setState] = useState<T>(initialState);
  const [history, setHistory] = useState<T[]>([initialState]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const isUndoRedoAction = useRef(false);

  const canUndo = currentIndex > 0;
  const canRedo = currentIndex < history.length - 1;

  // Set state and update history
  const set = useCallback(
    (newState: T | ((prev: T) => T)) => {
      // Don't add to history if this is an undo/redo action
      if (isUndoRedoAction.current) {
        isUndoRedoAction.current = false;
        return;
      }

      setState((prevState) => {
        const nextState =
          typeof newState === 'function'
            ? (newState as (prev: T) => T)(prevState)
            : newState;

        // Add to history
        setHistory((prevHistory) => {
          // Remove any "future" history when making a new change
          const newHistory = prevHistory.slice(0, currentIndex + 1);
          newHistory.push(nextState);

          // Limit history size
          if (newHistory.length > maxHistory) {
            newHistory.shift();
            setCurrentIndex((prev) => prev - 1);
          }

          return newHistory;
        });

        setCurrentIndex((prev) => Math.min(prev + 1, maxHistory - 1));

        return nextState;
      });
    },
    [currentIndex, maxHistory]
  );

  // Undo to previous state
  const undo = useCallback(() => {
    if (!canUndo) return;

    isUndoRedoAction.current = true;
    const prevIndex = currentIndex - 1;
    const prevState = history[prevIndex];

    setCurrentIndex(prevIndex);
    setState(prevState);
    onUndo?.(prevState);
  }, [canUndo, currentIndex, history, onUndo]);

  // Redo to next state
  const redo = useCallback(() => {
    if (!canRedo) return;

    isUndoRedoAction.current = true;
    const nextIndex = currentIndex + 1;
    const nextState = history[nextIndex];

    setCurrentIndex(nextIndex);
    setState(nextState);
    onRedo?.(nextState);
  }, [canRedo, currentIndex, history, onRedo]);

  // Reset history
  const reset = useCallback((newState?: T) => {
    const resetState = newState ?? initialState;
    setState(resetState);
    setHistory([resetState]);
    setCurrentIndex(0);
  }, [initialState]);

  // Clear future history
  const clearRedo = useCallback(() => {
    setHistory((prevHistory) => prevHistory.slice(0, currentIndex + 1));
  }, [currentIndex]);

  return {
    state,
    setState: set,
    undo,
    redo,
    canUndo,
    canRedo,
    reset,
    clearRedo,
    history,
    currentIndex,
    historyLength: history.length,
  };
}
"}

